"""Capture routing and storage in an isolated local browser; no device camera required."""
import json


def run_mobile_capture_checks(*, cdp, evaluate, check, wait_for, load, add, select, click_selector, shot):
    galaxy = add('Capture trip')
    owner = add('Travel photos', galaxy)
    other = add('Packing list', galaxy)
    wait_for('physics.settled')
    evaluate('physics.pause()')
    select(owner)
    # Suppress native dialogs only; exercise the real buttons, change handlers,
    # validation, repository transaction and IndexedDB storage below.
    evaluate("""window.capturePickers=[];[contentInspector.files,contentInspector.photoFiles,contentInspector.cameraFiles].forEach(input=>input.click=function(){capturePickers.push({accept:this.getAttribute('accept'),capture:this.getAttribute('capture'),multiple:this.multiple,label:this.getAttribute('aria-label')});});""")
    evaluate(f"toggleContentMenu(addMenu,hierarchySidebar.rows.get({json.dumps(owner)}).querySelector('.tree-add'),{json.dumps(owner)})")
    check(evaluate("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent).join('|')==='Add item|Add task list|Add files|Add note|Add link'"), 'desktop Add retains core actions without linked-item creation or empty-clipboard Paste')
    evaluate("addMenu.querySelector('[data-add=files]').click()")
    check(evaluate("capturePickers.at(-1).accept===null&&capturePickers.at(-1).capture===null&&capturePickers.at(-1).multiple"), 'desktop Files keeps the ordinary multiple-file picker')
    evaluate("(contentInspector.fileSelection?.input||contentInspector.files).dispatchEvent(new Event('cancel'));closeInspector()")

    def mobile(width, height):
        cdp.call('Emulation.setDeviceMetricsOverride', width=width, height=height, deviceScaleFactor=1, mobile=True)
        cdp.call('Emulation.setTouchEmulationEnabled', enabled=True, maxTouchPoints=5)
        wait_for('hierarchySidebar.narrow')
        evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')

    def cancel():
        evaluate("(contentInspector.fileSelection?.input||contentInspector.files).dispatchEvent(new Event('cancel'))")

    mobile(390, 844)
    evaluate(f"closeInspector();hierarchySidebar.setCollapsed(true);nodes.get({json.dumps(owner)}).click()")
    check(evaluate(f"panel.hidden&&selectedNode.dataset.entryId==={json.dumps(owner)}&&document.getElementById('mobile-body-actions').getClientRects().length>0"), 'mobile body selection exposes capture/actions without opening Contents')
    check(evaluate("(()=>{const a=document.getElementById('mobile-body-add').getBoundingClientRect(),m=document.getElementById('mobile-body-more').getBoundingClientRect();return a.width>=44&&m.width>=44&&a.right<=m.left;})()"), 'canvas + and actions have separate nonoverlapping 44px targets')
    def tap(selector):
        point = evaluate(f"(()=>{{const r=document.querySelector({json.dumps(selector)}).getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}};}})()")
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[point])
        cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[])

    # Both shared capture surfaces must expose the same native routes. Exercise
    # actual touch dispatch and cancellation without mutating saved metadata.
    for surface,trigger,expanded in [('Preview Contents','#mobile-body-add',False),('Contents','#entry-add-button',True)]:
        for action,input_id,capture,accept,multiple in [
                ('camera','content-camera','environment','image/*',False),
                ('photo','content-photos',None,'image/*',True),
                ('capture-files','content-files',None,None,True)]:
            evaluate('hierarchySidebar.setCollapsed(true);'+('setInspectorOpen(true);mobileContents.setPage("files")' if expanded else 'closeInspector()'))
            saved=evaluate('localStorage.getItem("galaxy:user-data")')
            tap(trigger);tap(f'#add-menu [data-add={action}]')
            check(evaluate(f'contentInspector.fileSelection.input.id==={json.dumps(input_id)}&&contentInspector.fileSelection.entryId==={json.dumps(owner)}&&capturePickers.at(-1).capture==={json.dumps(capture)}&&capturePickers.at(-1).accept==={json.dumps(accept)}&&capturePickers.at(-1).multiple==={str(multiple).lower()}'), f'{surface}: {action} reuses the existing native picker and exact destination')
            check(evaluate(f'panel.hidden==={str(not expanded).lower()}&&addMenu.hidden'), f'{surface}: {action} waits for a result without changing the content surface')
            cancel()
            check(evaluate('contentInspector.fileSelection===null&&document.getElementById("content-file-limit").hidden') and evaluate('localStorage.getItem("galaxy:user-data")')==saved, f'{surface}: {action} cancellation clears its destination without saving')

    evaluate('closeInspector()')
    evaluate(f"focusEntry({json.dumps(owner)},{{closeFocus:true,openInspector:false}})")
    wait_for('camera.frame===null')
    tap(f'.entry-node[data-entry-id="{owner}"]')
    check(evaluate(f'panel.hidden&&selectedNode.dataset.entryId==={json.dumps(owner)}'), 'a real body tap selects its body and leaves Contents closed')
    tap('#mobile-body-add')
    quick_labels = 'Take a photo|Add photo|Add files|Add item|Add task list'
    sidebar_labels = quick_labels
    def labels():
        return evaluate("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent).join('|')")

    check(labels() == quick_labels, 'Preview Contents has camera, photo, files, Add item and Add task list')
    check(evaluate("!addMenu.querySelector('[data-add=more]')&&!addMenu.querySelector('[data-add=quick-note]')&&!addMenu.querySelector('[data-add=camera]').hidden&&!addMenu.querySelector('[data-add=gallery]')"), 'compact menu exposes camera directly without duplicate sources or a second page')
    check(evaluate("addMenu.dataset.view==='quick'&&addMenu.querySelectorAll('[role=separator]:not([hidden])').length===0"), 'quick menu has no hidden full-menu actions exposed or group dividers')
    shot('mobile-capture-390-menu')
    preview_destination = evaluate('addMenuTargetId')
    evaluate('closeContentMenus();setInspectorOpen(true)')
    tap('#entry-add-button')
    check(labels() == quick_labels and evaluate('addMenuTargetId') == preview_destination, 'Contents header + opens exactly the preview quick menu for the same body')
    check(evaluate("addMenuTrigger.id==='entry-add-button'&&document.getElementById('entry-add-button').getAttribute('aria-expanded')==='true'"), 'Contents Add uses the shared menu trigger and expanded state')
    shot('mobile-capture-390-contents-menu')
    cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
    cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Escape',code='Escape',windowsVirtualKeyCode=27)
    check(evaluate("addMenu.hidden&&document.activeElement.id==='entry-add-button'&&document.activeElement.getAttribute('aria-expanded')==='false'"), 'Contents menu Escape restores its header + and clears expanded state')
    tap('#entry-add-button'); tap('#entry-add-button')
    check(evaluate('addMenu.hidden'), 'Contents + toggles the shared Add menu closed on a second tap')
    check(evaluate("['files','media','bookmark','location'].every((kind,i)=>document.getElementById('content-add-'+kind).textContent===['Add file…','Add media','Add link…','Add location…'][i])"), 'mobile section entry points use the approved explicit add wording')
    shot('mobile-capture-390-contents-header')
    tap('#content-browse-add-file')
    check(evaluate("capturePickers.at(-1).accept===null&&capturePickers.at(-1).capture===null&&capturePickers.at(-1).multiple&&addMenu.hidden&&!panel.hidden"), 'Add file retains its original section-specific picker without opening the body Add menu')
    cancel()
    evaluate('closeInspector()')
    tap('#mobile-body-add')
    before = evaluate("localStorage.getItem('galaxy:user-data')")
    tap('#add-menu [data-add=photo]')
    check(evaluate("capturePickers.at(-1).capture===null&&capturePickers.at(-1).accept==='image/*'&&capturePickers.at(-1).multiple&&panel.hidden&&addMenu.hidden"), 'Add photo requests images including HEIF without camera-only capture')
    cancel()
    check(evaluate("panel.hidden&&contentInspector.fileSelection===null&&document.getElementById('content-file-limit').hidden"), 'camera cancellation clears picker state and leaves Contents closed')
    check(evaluate("localStorage.getItem('galaxy:user-data')") == before, 'cancel does not write metadata')
    click_selector('#mobile-body-add'); click_selector('#add-menu [data-add=capture-files]')
    check(evaluate("capturePickers.at(-1).capture===null&&capturePickers.at(-1).accept===null&&capturePickers.at(-1).multiple&&panel.hidden"), 'repeated native picker allows all supported photos and files')
    cancel()
    evaluate('setInspectorOpen(true);mobileContents.setPage("files")')
    tap('#content-browse-add-file')
    check(evaluate("capturePickers.at(-1).capture===null&&capturePickers.at(-1).accept===null&&capturePickers.at(-1).multiple"), 'Files resets both camera and gallery filters')
    cancel()
    evaluate('closeInspector()')
    click_selector('#mobile-body-add')
    check(labels() == quick_labels, 'reopening CB + retains compact actions')
    click_selector('#add-child-button')
    check(evaluate(f"dialog.open&&contextualParentId==={json.dumps(owner)}&&parentField.value==={json.dumps(owner)}&&addMenu.hidden"), 'Add item opens the existing child form for the exact body')
    click_selector('#cancel-add-entry')
    evaluate('setInspectorOpen(true);mobileContents.setPage("notes")')
    tap('#content-browse-add-note')
    check(evaluate(f"contentInspector.entryId==={json.dumps(owner)}&&!contentInspector.notesForm.hidden"), 'Contents Notes retains its existing note editor')
    evaluate("document.getElementById('content-cancel-notes').click();closeInspector()")
    click_selector('#mobile-body-more')
    check(evaluate("!contextMenu.hidden&&contextMenu.getAttribute('aria-label').includes('Travel photos')&&addMenu.hidden"), 'separate canvas actions opens the existing item menu')
    evaluate('closeContextMenu(true)')
    check(evaluate("document.getElementById('mobile-body-more').getAttribute('aria-expanded')==='false'"), 'closing actions clears expanded state')

    for width, height in [(360, 800), (390, 844), (430, 932), (844, 390)]:
        mobile(width, height)
        evaluate('closeInspector();hierarchySidebar.setCollapsed(false)')
        check(evaluate("[...document.querySelectorAll('.hierarchy-row[data-entry-id]')].every(row=>{const a=row.querySelector('.tree-add'),m=row.querySelector('.tree-more').getBoundingClientRect();return a.hidden&&a.tabIndex===-1&&a.getClientRects().length===0&&m.width>=44&&m.right<=innerWidth;})"), f'{width}x{height}: rows retain management without +')
        check(evaluate("document.getElementById('add-entry-button').getClientRects().length>0"), f'{width}x{height}: Universe keeps New Galaxy +')
        evaluate('hierarchySidebar.setCollapsed(true)')
        tap('#mobile-body-add')
        check(labels() == quick_labels, f'{width}x{height}: Preview Contents retains all capture actions')
        check(evaluate("addMenu.dataset.view==='quick'&&addMenu.querySelectorAll('[role=separator]:not([hidden])').length===0"), f'{width}x{height}: no expanded mobile Add menu or unnecessary separators')
        check(evaluate("(()=>{const r=addMenu.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight&&r.width<=270;})()"), f'{width}x{height}: full Add menu stays inside viewport')
        check(evaluate("(()=>{const a=getComputedStyle(addMenu),m=getComputedStyle(contextMenu),ab=getComputedStyle(addMenu.querySelector('[data-add=capture-files]')),mb=getComputedStyle(contextMenu.querySelector('[data-action=edit]'));return ['backgroundColor','borderRadius','padding','boxShadow','borderColor','borderWidth'].every(k=>a[k]===m[k])&&['fontSize','fontFamily','padding','borderRadius','minHeight','color'].every(k=>ab[k]===mb[k]);})()"), f'{width}x{height}: Add surface and rows match the existing actions menu')
        shot(f'mobile-capture-{width}-drawer')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        check(evaluate("addMenu.hidden&&document.activeElement.id==='mobile-body-add'"), f'{width}x{height}: Escape returns to Preview Contents +')
        evaluate('hierarchySidebar.setCollapsed(true);setInspectorOpen(true);panel.scrollTop=0')
        tap('#contents-tab-files')
        check(evaluate("(()=>{const a=document.getElementById('entry-add-button').getBoundingClientRect(),m=moreButton.getBoundingClientRect(),n=panelName.getBoundingClientRect();return a.width>=44&&a.height>=44&&a.left>=n.right&&a.right<=m.left&&m.right<=innerWidth&&n.width>0;})()"), f'{width}x{height}: Contents title, body + and existing actions remain separate and reachable')
        check(evaluate("(()=>{const a=document.getElementById('content-browse-add-file'),r=a.getBoundingClientRect();return a.textContent==='Add file…'&&r.width>=44&&r.height>=44&&r.right<=innerWidth;})()"), f'{width}x{height}: mobile Add file stays readable with a touch target')
        tap('#entry-add-button')
        check(labels() == quick_labels and evaluate('addMenuTargetId') == owner, f'{width}x{height}: Contents header retains quick choices and exact body identity')
        check(evaluate("(()=>{const r=addMenu.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight;})()"), f'{width}x{height}: Contents Add menu stays within the viewport')
        shot(f'mobile-capture-{width}-contents-menu')
        evaluate('closeContentMenus();closeInspector()')
    mobile(390, 844)
    evaluate('hierarchySidebar.setCollapsed(true)')
    # Main-screen creation retains the selected destination without sidebar +.
    evaluate(f"selectEntry(entries.get({json.dumps(owner)}),nodes.get({json.dumps(owner)}),{{openInspector:false}});closeInspector();hierarchySidebar.setCollapsed(true)")
    tap('#mobile-body-add')
    check(labels() == sidebar_labels, 'Preview trigger retains its compact contextual menu')
    evaluate("document.getElementById('add-child-button').click()")
    check(evaluate(f"dialog.open&&contextualParentId==={json.dumps(owner)}&&parentField.value==={json.dumps(owner)}"), 'Add item preserves the selected main-screen destination')
    evaluate('document.getElementById("cancel-add-entry").click()')
    evaluate('closeContentMenus()')
    # Create a genuine PNG with the browser, then change selection before delivery.
    evaluate(f"openEntryContentAction({json.dumps(owner)},'photo');selectEntry(entries.get({json.dumps(other)}),nodes.get({json.dumps(other)}),{{openInspector:false}})")
    evaluate("""(async()=>{const c=document.createElement('canvas');c.width=80;c.height=60;c.getContext('2d').fillRect(0,0,80,60);const blob=await new Promise(r=>c.toBlob(r,'image/png'));window.capturePhoto=new File([blob],'camera-photo.png',{type:'image/png'});const d=new DataTransfer();d.items.add(capturePhoto);(contentInspector.fileSelection?.input||contentInspector.files).files=d.files;(contentInspector.fileSelection?.input||contentInspector.files).dispatchEvent(new Event('change'));})()""")
    wait_for('contentInspector.jobs.size===0&&contentInspector.content().attachments.length===1')
    check(evaluate(f"!panel.hidden&&contentInspector.entryId==={json.dumps(owner)}&&!(entries.get({json.dumps(other)}).content?.attachments.length)"), 'picker result attaches to its original destination after selection changes')
    check(evaluate("(async()=>{const f=contentInspector.content().attachments[0],r=await attachmentStore.get(f.storageKey);return r.entryId===f.entryId&&r.blob.size===capturePhoto.size&&!!r.thumbnail&&f.width===80&&f.height===60;})()"), 'capture uses existing original-byte and thumbnail storage transaction')
    evaluate("document.querySelector('#content-media .content-media-viewport').click()")
    wait_for('imageViewer.dialog.open&&!imageViewer.image.hidden')
    check(evaluate('imageViewer.image.naturalWidth===80'), 'existing image lightbox still opens captured photos')
    evaluate('imageViewer.dialog.close()')
    evaluate("contentInspector.upload([new File(['blocked'],'unsafe.exe',{type:'image/jpeg'})])")
    wait_for('contentInspector.jobs.size===0')
    check(evaluate("contentInspector.content().attachments.length===1&&!contentInspector.status.hidden&&contentInspector.status.dataset.error==='true'&&contentInspector.status.textContent.includes('Executable')"), 'capture does not bypass executable restrictions; failure leaves existing photo intact')
    # Unsupported native HEIF decode must remain a recoverable original.
    evaluate("window.originalBitmap=createImageBitmap;window.createImageBitmap=()=>Promise.reject(Error('unsupported HEIF'));contentInspector.upload([new File(['original HEIF bytes'],'original.heic',{type:'image/heic'})])")
    wait_for('contentInspector.jobs.size===0&&contentInspector.content().attachments.length===2')
    check(evaluate("(async()=>{const f=contentInspector.content().attachments[1],r=await attachmentStore.get(f.storageKey);return f.filename==='original.heic'&&await r.blob.text()==='original HEIF bytes'&&!r.thumbnail&&galaxyModel.filePolicy.isMedia(f);})()"), 'unsupported HEIF retains original bytes as Media without a destructive conversion')
    evaluate('window.createImageBitmap=originalBitmap')
    evaluate("document.querySelectorAll('#content-media .content-media-viewport')[1].click()")
    wait_for("imageViewer.dialog.open&&imageViewer.status.textContent.includes('Preview unavailable')")
    check(evaluate('!imageViewer.saveCopy.hidden'), 'unsupported HEIF viewer retains Save a copy fallback')
    check(evaluate("(async()=>await (await fetch(imageViewer.saveCopy.href)).text()==='original HEIF bytes')()"), 'unsupported HEIF Save a copy points to the original bytes')
    shot('mobile-capture-heif-fallback')
    # Fixture-only thumbnail injection. Ordinary F4 saves correctly reject an
    # existing key; this does not exercise or bypass a product mutation path.
    evaluate("""imageViewer.dialog.close();(async()=>{const f=contentInspector.content().attachments[1],r=await attachmentStore.get(f.storageKey);
        const db=await new Promise((resolve,reject)=>{const request=indexedDB.open('galaxy-attachments');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});
        try{await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);tx.objectStore('files').put({...r,thumbnail:capturePhoto});});}finally{db.close();}})()""")
    evaluate("document.querySelectorAll('#content-media .content-media-viewport')[1].click()")
    wait_for('imageViewer.dialog.open&&!imageViewer.image.hidden')
    check(evaluate("(async()=>imageViewer.image.naturalWidth===80&&imageViewer.url!==imageViewer.originalUrl&&await(await fetch(imageViewer.infoCopy.href)).text()==='original HEIF bytes')()"), 'friendly HEIF preview displays while Info download retains the original')
    evaluate('imageViewer.dialog.close();closeInspector()')
    wait_for('!imageViewer.dialog.open&&imageViewer.originalUrl===null&&imageViewer.url===null')
    check(evaluate('imageViewer.originalUrl===null&&imageViewer.url===null'), 'closing preview releases original and preview object URLs')
    click_selector('#mobile-body-contents')
    check(evaluate('!panel.hidden'), 'Contents remains explicitly accessible after mobile navigation')
    # The quick-capture menu is independent of role, page and sheet disclosure.
    evaluate(f'createChildEntry({json.dumps(galaxy)},true);fields[0].value="Capture tasks";document.getElementById("task-list-tasks").value="Individual capture task";form.requestSubmit();applicationCommandTail')
    wait_for('!formSaveBusy&&!dialog.open')
    task=evaluate('galaxyModel.childrenOf(entries,selectedNode.dataset.entryId)[0].id')
    task_labels='Take a photo|Add photo|Add files'
    for width,height in [(390,844),(844,390)]:
        mobile(width,height)
        for target,expected in [(owner,quick_labels),(task,task_labels)]:
            evaluate(f'selectEntry(entries.get({json.dumps(target)}),nodes.get({json.dumps(target)}),{{openInspector:false,reframe:false}});closeInspector();hierarchySidebar.setCollapsed(true);physics.pause()')
            tap('#mobile-body-add')
            check(labels()==expected,f'{width}: compact quick menu preserves exact normal/Task actions for {target}')
            evaluate('closeContentMenus();setInspectorOpen(true)')
            for page in ['files','notes','links','location']:
                evaluate(f'mobileContents.setPage({json.dumps(page)})')
                tap('#entry-add-button')
                check(labels()==expected,f'{width}: expanded {page} keeps Add files and the correct structural actions for {target}')
                check(evaluate("!addMenu.querySelector('[data-add=capture-files]').hidden"),f'{width}: Add files remains a predictable quick action on {page}')
                evaluate('closeContentMenus()')
            if target==task:
                evaluate('mobileContents.setPage("files")')
                check(evaluate('!document.getElementById("entry-add-button").hidden&&document.getElementById("content-browse-add-file").getClientRects().length>0'),'Task keeps header quick add and direct Files control together')
    mobile(390,844)
    for expanded,trigger in [(False,'#mobile-body-add'),(True,'#entry-add-button')]:
        for action,input_id in [('camera','content-camera'),('photo','content-photos'),('capture-files','content-files')]:
            evaluate(f'selectEntry(entries.get({json.dumps(task)}),nodes.get({json.dumps(task)}),{{openInspector:true,reframe:false}});hierarchySidebar.setCollapsed(true);'+('mobileContents.setPage("files")' if expanded else 'closeInspector()'))
            saved=evaluate('localStorage.getItem("galaxy:user-data")')
            tap(trigger);tap(f'#add-menu [data-add={action}]')
            check(evaluate(f'contentInspector.fileSelection.entryId==={json.dumps(task)}&&contentInspector.fileSelection.input.id==={json.dumps(input_id)}'),'Task capture reuses original picker and destination: '+action+' / '+str(expanded))
            cancel()
            check(evaluate('contentInspector.fileSelection===null') and evaluate('localStorage.getItem("galaxy:user-data")')==saved,'Task picker cancellation leaves persistence unchanged: '+action+' / '+str(expanded))
    for width in [900,1440]:
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=1000,deviceScaleFactor=1,mobile=False)
        cdp.call('Emulation.setTouchEmulationEnabled',enabled=False)
        wait_for('!hierarchySidebar.narrow')
        evaluate(f'selectEntry(entries.get({json.dumps(task)}),nodes.get({json.dumps(task)}),{{openInspector:true,reframe:false}});physics.pause()')
        check(evaluate("document.getElementById('entry-add-button').hidden&&moreButton.getClientRects().length>0"),f'{width}: desktop/tablet Task hides structural + and retains management')
        evaluate("document.getElementById('entry-add-button').click()")
        check(evaluate("addMenu.hidden&&document.getElementById('entry-add-button').getAttribute('aria-expanded')==='false'"),f'{width}: empty Task menu cannot open after mobile-to-desktop resize')
        evaluate(f'selectEntry(entries.get({json.dumps(owner)}),nodes.get({json.dumps(owner)}),{{openInspector:true,reframe:false}});document.getElementById("entry-add-button").click()')
        check(labels()=='Add item|Add task list' and evaluate("!document.getElementById('entry-add-button').hidden"),f'{width}: normal CB restores desktop structural +')
        evaluate('closeContentMenus()')
    check(not cdp.errors, f'no capture browser exceptions: {cdp.errors}')
